const tokens = data.split(/\s+/).filter(s => s.length > 0);
const d = tokens[0];
const n = d.length;
let i, j;
let dot = 0;
let e = 0;
for (i = 0; i < n; i++) {
    if (d[i] === '.') {
        dot = i;
    }
    if (d[i] === 'e') {
        e = i;
        break;
    }
}
let b = "";
let nb = 0;
for (j = e + 1; j < n; j++) {
    b += d[j];
    nb++;
}
let xb = 0;
for (i = 0; i < nb; i++) {
    xb = xb * 10 + (b.charCodeAt(i) - 48);
}
let out = "";
for (i = 0; i < n; i++) {
    if (d[i] === '.') {
        if (e - dot === 2 && d[dot + 1] === '0') {
            break;
        }
    } else if (d[i] === 'e') {
        break;
    } else {
        if (i === dot + xb + 1) {
            out += ".";
        }
        out += d[i];
    }
}
let zero = xb - (e - dot - 1);
if (e - dot === 2 && d[dot + 1] === '0') {
    zero = xb;
}
for (i = 0; i < zero; i++) {
    out += "0";
}
out += "\n";
process.stdout.write(out);
